import { Component, Input, OnInit, SimpleChanges, OnChanges } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { ICampaignTrackingInfo, IMagCampaignLayoutConfig, IPreparedTrackingZoneData } from '../../model/interface';
import { DXPTracker } from '@rsApp/modules/utils/providers/dxp-tracker.service';
import { getDXPagesTrackingPageView, prepareTrackingZoneData } from '../../dxpage.utils';

@Component({
  selector: 'dxpage-custom-layout',
  templateUrl: './dxpage-custom-layout.html',
  styleUrls: ['./dxpage-custom-layout.scss'],
})
export class DXPageCustomLayoutComponent implements OnInit, OnChanges {
  @Input() layoutConfig: IMagCampaignLayoutConfig;
  @Input() trackInfo: ICampaignTrackingInfo;

  utmSource: string;
  utmMedium: string;

  trackedZoneData: IPreparedTrackingZoneData;

  constructor(
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    private dxpTracking: DXPTracker
  ) {}

  ngOnInit() {
    this.trackedZoneData = prepareTrackingZoneData(this.layoutConfig, this.trackInfo);
  }

  /**
   * Angular lifecycle hook. Called after a bound input property changes.
   * Trigger page view tracking if the `trackInfo` input property is changed and the page is actived.
   * @param changes The changes object containing the SimpleChange objects.
   */
  ngOnChanges(changes: SimpleChanges) {
    if (changes['trackInfo']) {
      const latestTrackInfo = changes['trackInfo'].currentValue;
      if (latestTrackInfo?.isActived) {
        this.utmSource = this.route.snapshot.paramMap.get('utm_source');
        this.utmMedium = this.route.snapshot.paramMap.get('utm_medium');

        const trackingPayload = getDXPagesTrackingPageView(
          this.layoutConfig,
          latestTrackInfo,
          this.utmSource,
          this.utmMedium,
          'trackDXPagesPageView'
        );
        const { eventName, payload } = trackingPayload || {};
        this.dxpTracking.handlePushDxpTracking(eventName, payload);
      }
    }
  }

  get wrapperStyles() {
    const background: any = this.layoutConfig.Styles?.Background || {};
    return {
      'background-image': background.Image ? `url(${background.Image})` : '',
      'background-size': background.Size || 'auto',
      'background-repeat': background.Repeat || 'no-repeat',
      'background-position': background.Position || 'center',
      'background-color': background.Color || 'transparent',
      width: '100%',
      'flex-shrink': '0',
      margin: '0 auto',
      display: 'flex',
      'max-width': '1240px',
      padding: ' 4px',
    };
  }

  getItemPadding(zoneData: IMagCampaignLayoutConfig) {
    const gap = Number(zoneData?.Styles?.Gap);
    const hasItems = zoneData?.ContentItems?.length;
    return `${gap && hasItems ? gap / 2 : 12}px`;
  }

  getClassNames(classNames: Record<string, string>, isParent?: boolean): string {
    return Object.values(classNames).join(' ') + `custom-layout ${isParent ? 'parent-zone' : ''}`;
  }
}
