import { IMagCampaignLayoutConfig, ICampaignTrackingInfo } from './model/interface';

//Tracking utils
export const mapDataSource = (dataSource, item) => {
  return {
    ItemID:
      dataSource?.ProductUpc || dataSource?.OfferCode || dataSource?.Url || item?.Fallback || item?.Thumbnail || '',
    ItemName: dataSource?.ProductName?.En || dataSource?.Name || dataSource?.OfferName || '',
    ItemSize: dataSource?.Unit || dataSource?.ApplyLimitByUser || '',
    ItemValue: dataSource?.Price || dataSource?.ShortName || '',
    ItemTemplateID: dataSource?.Template?.Id || '',
  };
};

export const mapContentItem = (item) => {
  return {
    CollectionID: item?.ContentItemId,
    CollectionName: item?.ContentItemName || '',
    CollectionType: item?.ContentType || '',
    TotalItems: item?.DataSources?.length || 0,
    ItemInfo: (item?.DataSources || [])?.map((dataSource) => {
      return mapDataSource(dataSource, item);
    }),
  };
};

export const mapZone = (zone) => {
  return {
    ZoneID: zone?.UId,
    ZoneName: zone?.Label || '',
    TotalCollections: zone?.ContentItems?.length || 0,
    CollectionInfo: (zone?.ContentItems || [])?.map((item) => {
      return mapContentItem(item);
    }),
  };
};

export const getTrackingDyanmicZone = (data) => {
  return (data?.Children || [])?.map((zone: any) => {
    return mapZone(zone);
  });
};

export const getDXPagesTrackingPageView = (
  data: IMagCampaignLayoutConfig,
  trackInfo: ICampaignTrackingInfo,
  utmSource: string,
  utmMedium: string,
  eventName: string
) => {
  const { CampaignId, CampaignStartDate, CampaignEndDate, TotalPages, PageID, CampaignCode, CampaignName, PageNumber } =
    trackInfo;

  const dynamicZones = getTrackingDyanmicZone(data);

  return {
    eventName: eventName,
    payload: {
      CampaignId: CampaignId,
      PageNumber: PageNumber,
      CampaignStartDate: CampaignStartDate || '',
      CampaignEndDate: CampaignEndDate || '',
      TotalPages: TotalPages || 0,
      PageID: PageID || '',
      PageInfo: {
        PageVersion: '', // TODO: Waiting for BE return value
        PageTemplateID: PageID || '',
        TotalZones: data?.Children?.length || 0,
        ZoneInfo: dynamicZones,
      },
      // extradata
      CampaignCode: CampaignCode || '',
      CampaignSource: utmSource || '', // Identifies where the traffic comes from
      CampaignMedium: utmMedium || '', // Describes how the traffic was acquired
      CampaignName: CampaignName || '',
      PreviousPage: document.referrer,
    },
  };
};

export const prepareTrackingZoneData = (zoneData: IMagCampaignLayoutConfig, trackInfo: ICampaignTrackingInfo) => {
  const updatedItems =
    zoneData.ContentItems?.map((item) => ({
      ...item,
      extendedTrackInfo: {
        ...trackInfo,
        ZoneID: zoneData?.UId || '',
        ZoneName: zoneData?.Label || '',
        CollectionID: item?.ContentItemId || '',
        CollectionName: item?.ContentItemName || '',
        CollectionType: item?.ContentType || '',
      },
    })) || [];

  return {
    ...zoneData,
    ContentItems: updatedItems,
    Children: zoneData.Children?.map((child) => {
      return prepareTrackingZoneData(child, trackInfo);
    }),
  };
};
