import { Component, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { firstValueFrom } from 'rxjs';
import { DXPageService } from '../../providers/dxpage.service';
import { ICampaignTrackingInfo, IMagCampaign, IMagCampaignAdLayout, ViewMode } from '../../model/interface';
import { IonContent } from '@ionic/angular';

@Component({
  selector: 'dxpage-detail',
  templateUrl: './dxpage-detail.html',
  styleUrls: ['./dxpage-detail.scss'],
})
export class DXPageDetailPageComponent {
  campaignDetail: IMagCampaignAdLayout;
  campaignName: string;
  activePage: number = 1;
  pageList: number[] = [];
  viewMode: string;
  campaignTrackingInfo: ICampaignTrackingInfo;

  @ViewChild(IonContent, { static: false }) contentEl: IonContent;

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    public dxPagesService: DXPageService
  ) {}

  async ionViewWillEnter() {
    const campaign = this.route.snapshot.paramMap.get('campaign');
    if (campaign) {
      await this.setup(campaign);
    }
  }

  async setup(campaignCode: string) {
    if (!campaignCode) {
      console.warn('Campaign code not found');
      return;
    }
    try {
      const data = await firstValueFrom(this.dxPagesService.getCampaign({ campaignCode }));
      this.campaignName = data?.Name;
      this.setupAdLayout(data?.AdLayout);
      if (this.campaignDetail) {
        this.setupTrackingInfo(data, this.campaignDetail);
      }
    } catch (error) {
      console.warn('Error fetching campaign details:', error);
    }
  }

  setupAdLayout(adLayout: string) {
    if (!adLayout) {
      console.warn('No AdLayout found in campaign data');
      return;
    }
    try {
      this.campaignDetail = JSON.parse(adLayout);
      this.campaignDetail.ViewMode = 'VERTICAL';
      this.viewMode = this.campaignDetail?.ViewMode;
      this.pageList = this.campaignDetail?.Pages?.map((_, idx) => idx + 1) || [1];
    } catch (error) {
      console.warn('Error parsing AdLayout JSON:', error);
    }
  }

  setupTrackingInfo(data: IMagCampaign, adLayout: IMagCampaignAdLayout) {
    const { Id, Code, Name, StartDate, EndDate } = data || {};
    const { Pages } = adLayout || {};
    this.campaignTrackingInfo = {
      CampaignId: Id,
      CampaignCode: Code,
      CampaignName: Name,
      CampaignStartDate: StartDate,
      CampaignEndDate: EndDate,
      TotalPages: Pages?.length,
      viewMode: ViewMode.VERTICAL,
    };
  }

  handleScrollToTop(event?) {
    if (this.viewMode !== 'VERTICAL') return;

    const firstPage = document.getElementById(`dxpage-vertical-${1}`);
    if (!firstPage) return;

    const scrollTop = event.detail.scrollTop; // ion-content's scroll position
    const elementTop = firstPage.offsetTop; // distance from ion-content top

    if (scrollTop < elementTop) {
      this.activePage = 1;
    }
  }

  // Handle mag-pagination-control scroll
  handleScroll(event?) {
    if (this.viewMode !== ViewMode.VERTICAL) return;
    const { detail } = event || {};
    const currentPage = document.getElementById(`dxpage-vertical-${detail}`);
    if (!currentPage) return;
    const yOffset = currentPage.offsetTop - 100;
    this.contentEl.scrollToPoint(0, yOffset, 500);
    this.activePage = detail;
  }
}
