export interface IMagCampaign {
  Id: string;
  Name: string;
  Code: string;
  Status: number;
  StartDate: string;
  EndDate: string;
  Notes: string;
  EditPermissionMode: number;
  Permissions: any[];
  Proofs: any[];
  AdLayout: string; // JSON String
}

export interface IMagCampaignAdLayout {
  Theme: 'DEFAULT' | string;
  ViewMode: 'HORIZONTAL' | 'VERTICAL' | 'PAGINATION';
  Pages: IMagCampaignPage[];
}

export interface IMagCampaignPage {
  Id: string;
  IsDynamicLayout: boolean;
  LayoutConfig: IMagCampaignLayoutConfig;
  IsExpanded?: boolean;
  IsRoot?: boolean;
  Widgets?: any[]; // Replace 'any' with specific widget type if available
  Styles?: Record<string, string>;
}

export interface IMagCampaignLayoutConfig {
  Label: string;
  UId: string;
  ClassNames: Record<string, string>;
  Children: IMagCampaignLayoutConfig[];
  IsExpanded: boolean;
  ContentItems?: ICampaignContentItem[];
  Styles?: Record<string, string>;
  IsRoot?: boolean;
  Widgets?: any[]; // Replace 'any' with specific widget type if available
}

interface ICampaignContentItem {
  ContentType: string;
  ContentItemId: string;
  ContentItemName: string;
  Thumbnail: string;
  Fallback: string;
  Description: string;
  DataSources: ICampaignContentItemProduct[] | any[]; //TODO: Replace 'any' with specific data source type
}

interface ICampaignContentItemProduct {
  ProductId: string;
  ProductUpc: string;
  ProductName: {
    En: string;
    [key: string]: string;
  };
  Price: number;
  DisplayPrice: string;
  Unit: string;
  MediaAssets: {
    Images: IImage[];
    Image360: null | any;
  };
}
export interface ICampaignTrackingInfo {
  isActived?: boolean;
  viewMode?: string;
  CampaignId: string;
  CampaignName?: string;
  CampaignCode?: string;
  CampaignSource?: string;
  CampaignMedium?: string;
  CampaignStartDate?: string;
  CampaignEndDate?: string;
  TotalPages?: number;
  PageID?: string;
  PageNumber?: number;
  [key: string]: any;
}

interface IImage {
  OriginalAssetId: string | null;
  ImgUrlOriginal: string;
  ImgUrlXLarge: string | null;
  ImgUrlLarge: string | null;
  ImgUrlMedium: string | null;
  ImgUrlSmall: string | null;
  IsDefault: boolean;
  DisplayOrder: number | null;
  ProductFace: number | null;
  ImageTypeCode: string | null;
}

export const ViewMode = {
  VERTICAL: 'VERTICAL',
  HORIZONTAL: 'HORIZONTAL',
  PAGINATION: 'PAGINATION',
};

export interface IPreparedTrackingZoneData extends Omit<IMagCampaignLayoutConfig, 'ContentItems' | 'Children'> {
  ContentItems?: (ICampaignContentItem & {
    extendedTrackInfo: ICampaignTrackingInfo & {
      ZoneID: string;
      ZoneName: string;
      CollectionID: string;
      CollectionName: string;
    };
  })[];
  Children?: IPreparedTrackingZoneData[];
}
