import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { DXPageModule } from './dxpage.module';
import { DXPageDetailPageComponent } from './pages/dxpage-detail/dxpage-detail';
import { DXPageListPageComponent } from './pages/dxpage-list/dxpage-list';

const routes: Routes = [
  {
    path: '',
    component: DXPageListPageComponent,
  },
  {
    path: ':campaign',
    component: DXPageDetailPageComponent,
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), DXPageModule],
  declarations: [],
})
export class DXPageRoutingModule {}
