import { Component, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'dxpage-list',
  templateUrl: './dxpage-list.html',
  styleUrls: ['./dxpage-list.scss'],
})
export class DXPageListPageComponent implements OnDestroy {
  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService
  ) {}

  ionViewWillEnter() {
    this.route.data.pipe(takeUntil(this._destroy$)).subscribe(() => {
      // This block will run after both data and queryParams have been processed
    });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }
}
