import { Inject, Injectable } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { CacheService } from 'ionic-cache';
import { map, Observable } from 'rxjs';
import { IMagCampaign } from '../model/interface';
import { MAG_DXPAGE_HTTP_CLIENT } from '../../utils/ecom-api-configs';

@Injectable()
export class DXPageService {
  constructor(
    public cache: CacheService,
    @Inject(MAG_DXPAGE_HTTP_CLIENT) private api: MagEComCoreApiHttpClient
  ) {}

  getCampaign(payload): Observable<IMagCampaign> {
    return this.api.get(`/Campaigns/by-code/${payload?.campaignCode}`).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }
}
